            { rank: 100, symbol: 'SLERF', name: 'Slerf', price: 0.285, change1h: 0.92, change24h: 5.85, change7d: 18.45, marketCap: 0.14e9, volume: 42.5e6, supply: '490M SLERF', network: 'solana', sparkline: [18, 22, 32, 48, 65, 78, 88, 94, 96, 98, 99, 100] }
        ];

        // ===== STATE =====
        let currentPage = 1;
        const itemsPerPage = 100;
        const totalAssets = 8364;
        const totalPages = Math.ceil(totalAssets / itemsPerPage);

        let activeCategory = 'top';
        let activeNetwork = 'all';
        let currentSort = 'marketCap';

        // ===== FORMATTING HELPERS =====
        function formatPrice(price) {
            if (price >= 1000) {
                return '$' + price.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
            } else if (price >= 1) {
                return '$' + price.toFixed(2);
            } else if (price >= 0.01) {
                return '$' + price.toFixed(4);
            } else {
                return '$' + price.toFixed(6);
            }
        }

        function formatLargeNumber(num) {
            if (num >= 1e12) return '$' + (num / 1e12).toFixed(2) + 'T';
            if (num >= 1e9) return '$' + (num / 1e9).toFixed(2) + 'B';
            if (num >= 1e6) return '$' + (num / 1e6).toFixed(2) + 'M';
            if (num >= 1e3) return '$' + (num / 1e3).toFixed(2) + 'K';
            return '$' + num.toFixed(2);
        }

        function formatPercent(value) {
            const sign = value >= 0 ? '+' : '';
            return sign + value.toFixed(2) + '%';
        }

        function getChangeClass(value) {
            return value >= 0 ? 'positive' : 'negative';
        }

        function generateSparklineHTML(data, baseValue = 50) {
            const max = Math.max(...data);
            const min = Math.min(...data);
            const range = max - min || 1;
            const bars = data.map((val, i) => {
                const height = ((val - min) / range * 24) + 8;
                const trend = val > data[0] ? 'up' : (val < data[0] ? 'down' : '');
                return `<div class="sparkline-bar ${trend}" style="height: ${height}px"></div>`;
            });
            return `<div class="sparkline">${bars.join('')}</div>`;
        }

        // ===== RENDER TABLE =====
        function renderTable() {
            const tbody = document.getElementById('cryptoTableBody');
            tbody.innerHTML = '';

            // Sort data
            let sortedData = [...cryptoData];
            if (currentSort === 'marketCap') {
                sortedData.sort((a, b) => b.marketCap - a.marketCap);
            } else if (currentSort === 'volume') {
                sortedData.sort((a, b) => b.volume - a.volume);
            } else if (currentSort === 'price') {
                sortedData.sort((a, b) => b.price - a.price);
            } else if (currentSort === 'change24h') {
                sortedData.sort((a, b) => b.change24h - a.change24h);
            }

            // Filter by network
            if (activeNetwork !== 'all') {
                sortedData = sortedData.filter(c => c.network === activeNetwork);
            }

            // Paginate
            const start = (currentPage - 1) * itemsPerPage;
            const end = start + itemsPerPage;
            const pageData = sortedData.slice(start, end);

            // Build rows
            pageData.forEach(crypto => {
                const row = document.createElement('tr');
                row.innerHTML = `
                    <td class="rank-col">${crypto.rank}</td>
                    <td class="name-col">
                        <div class="crypto-name">
                            <div class="crypto-icon">${crypto.symbol.charAt(0)}</div>
                            <div class="crypto-info">
                                <span class="crypto-symbol">${crypto.symbol}</span>
                                <span class="crypto-fullname">${crypto.name}</span>
                            </div>
                        </div>
                    </td>
                    <td class="num price-col">${formatPrice(crypto.price)}</td>
                    <td class="num change-col ${getChangeClass(crypto.change1h)}">${formatPercent(crypto.change1h)}</td>
                    <td class="num change-col ${getChangeClass(crypto.change24h)}">${formatPercent(crypto.change24h)}</td>
                    <td class="num change-col ${getChangeClass(crypto.change7d)}">${formatPercent(crypto.change7d)}</td>
                    <td class="num market-cap-col">${formatLargeNumber(crypto.marketCap)}</td>
                    <td class="num volume-col">${formatLargeNumber(crypto.volume)}</td>
                    <td class="num supply-col">${crypto.supply}</td>
                    <td class="sparkline-col">${generateSparklineHTML(crypto.sparkline)}</td>
                `;
                tbody.appendChild(row);
            });
        }

        // ===== RENDER PAGINATION =====
        function renderPagination() {
            const container = document.getElementById('paginationControls');
            container.innerHTML = '';

            // Previous button
            const prevBtn = document.createElement('button');
            prevBtn.className = 'page-btn';
            prevBtn.textContent = '◀';
            prevBtn.disabled = currentPage === 1;
            prevBtn.onclick = () => goToPage(currentPage - 1);
            container.appendChild(prevBtn);

            // Page numbers
            const maxVisible = 5;
            let startPage = Math.max(1, currentPage - Math.floor(maxVisible / 2));
            let endPage = Math.min(totalPages, startPage + maxVisible - 1);

            if (endPage - startPage < maxVisible - 1) {
                startPage = Math.max(1, endPage - maxVisible + 1);
            }

            if (startPage > 1) {
                const firstBtn = document.createElement('button');
                firstBtn.className = 'page-btn';
                firstBtn.textContent = '1';
                firstBtn.onclick = () => goToPage(1);
                container.appendChild(firstBtn);

                if (startPage > 2) {
                    const ellipsis = document.createElement('span');
                    ellipsis.className = 'page-ellipsis';
                    ellipsis.textContent = '...';
                    container.appendChild(ellipsis);
                }
            }

            for (let i = startPage; i <= endPage; i++) {
                const btn = document.createElement('button');
                btn.className = 'page-btn' + (i === currentPage ? ' active' : '');
                btn.textContent = i;
                btn.onclick = () => goToPage(i);
                container.appendChild(btn);
            }

            if (endPage < totalPages) {
                if (endPage < totalPages - 1) {
                    const ellipsis = document.createElement('span');
                    ellipsis.className = 'page-ellipsis';
                    ellipsis.textContent = '...';
                    container.appendChild(ellipsis);
                }

                const lastBtn = document.createElement('button');
                lastBtn.className = 'page-btn';
                lastBtn.textContent = totalPages;
                lastBtn.onclick = () => goToPage(totalPages);
                container.appendChild(lastBtn);
            }

            // Next button
            const nextBtn = document.createElement('button');
            nextBtn.className = 'page-btn';
            nextBtn.textContent = '▶';
            nextBtn.disabled = currentPage === totalPages;
            nextBtn.onclick = () => goToPage(currentPage + 1);
            container.appendChild(nextBtn);
        }

        function goToPage(page) {
            currentPage = page;
            renderTable();
            renderPagination();
        }

        // ===== PANEL TOGGLES =====
        function togglePanel(panelId) {
            const panel = document.getElementById(panelId);
            const btn = panelId === 'columnsPanel' ? document.getElementById('columnsBtn') : document.getElementById('filtersBtn');

            if (panel.classList.contains('active')) {
                panel.classList.remove('active');
                btn.classList.remove('active');
            } else {
                panel.classList.add('active');
                btn.classList.add('active');
            }
        }

        // ===== MARKET SUMMARY TOGGLE =====
        function toggleMarketSummary() {
            const expanded = document.getElementById('expandedContent');
            const btn = document.getElementById('readMoreBtn');

            expanded.classList.toggle('active');
            btn.textContent = expanded.classList.contains('active') ? 'Read Less ▲' : 'Read More ▾';
        }

        // ===== PROMO ROTATION =====
        const promoTexts = [
            'CTP Launch: Secure $GENIUS Airdrop — Join Now',
            'Trade with 0 fees on all BTC pairs this week',
            'New: Advanced charts with custom timeframes',
            'Stake ETH and earn up to 5.2% APY'
        ];
        let promoIndex = 0;

        function rotatePromo(direction) {
            promoIndex = (promoIndex + direction + promoTexts.length) % promoTexts.length;
            const carousel = document.getElementById('promoCarousel');
            carousel.innerHTML = `<span class="promo-text">${promoTexts[promoIndex]}</span>`;
        }

        // Auto-rotate promo
        setInterval(() => rotatePromo(1), 5000);

        // ===== EVENT LISTENERS =====

        // Category tabs
        document.querySelectorAll('.category-tab').forEach(tab => {
            tab.addEventListener('click', () => {
                document.querySelectorAll('.category-tab').forEach(t => t.classList.remove('active'));
                tab.classList.add('active');
                activeCategory = tab.dataset.category;
            });
        });

        // Network tabs
        document.querySelectorAll('.network-tab').forEach(tab => {
            tab.addEventListener('click', () => {
                document.querySelectorAll('.network-tab').forEach(t => t.classList.remove('active'));
                tab.classList.add('active');
                activeNetwork = tab.dataset.network;
                currentPage = 1;
                renderTable();
                renderPagination();
            });
        });

        // Sort buttons
        document.querySelectorAll('.sort-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                document.querySelectorAll('.sort-btn').forEach(b => b.classList.remove('active'));
                btn.classList.add('active');
                currentSort = btn.dataset.sort;
                currentPage = 1;
                renderTable();
                renderPagination();
            });
        });

        // Column toggles
        document.querySelectorAll('.column-toggle input').forEach(input => {
            input.addEventListener('change', () => {
                const column = input.dataset.column;
                const cells = document.querySelectorAll(`td:nth-child(${getColumnIndex(column)}), th:nth-child(${getColumnIndex(column)})`);
                cells.forEach(cell => {
                    cell.style.display = input.checked ? '' : 'none';
                });
            });
        });

        function getColumnIndex(column) {
            const columns = ['rank', 'name', 'price', '1h', '24h', '7d', 'marketCap', 'volume', 'supply', 'sparkline'];
            return columns.indexOf(column) + 1;
        }

        // ===== INITIALIZE =====
        document.addEventListener('DOMContentLoaded', () => {
            renderTable();
            renderPagination();
        });
    </script>
</body>
